        // ============ AUDIO SYSTEM ============
        class AudioSystem {
            constructor() {
                this.ctx = null;
                this.initialized = false;
                this.listener = null;
                this.masterGain = null;
                this.volume = 0.6;
                this.init();
            }
            init() {
                try {
                    this.ctx = new(window.AudioContext || window.webkitAudioContext)();
                    this.masterGain = this.ctx.createGain();
                    this.masterGain.gain.value = this.volume;
                    this.masterGain.connect(this.ctx.destination);
                    this.initialized = true;
                } catch (e) {
                    console.log('Audio init failed');
                }
            }
            resume() {
                if (this.ctx && this.ctx.state === 'suspended') this.ctx.resume();
            }
            now() { return this.ctx ? this.ctx.currentTime : 0; }

            playNoise(duration, freq, gainVal, type = 'sawtooth', freqEnd = null) {
                if (!this.ctx || !this.initialized) return;
                const t0 = this.now();
                const dur = Math.min(duration, 2);
                const osc = this.ctx.createOscillator();
                const gain = this.ctx.createGain();
                const filter = this.ctx.createBiquadFilter();
                osc.type = type;
                osc.frequency.setValueAtTime(freq, t0);
                if (freqEnd) osc.frequency.exponentialRampToValueAtTime(Math.max(20, freqEnd), t0 + dur);
                else osc.frequency.exponentialRampToValueAtTime(Math.max(20, freq * 0.25), t0 + dur);
                gain.gain.setValueAtTime(gainVal, t0);
                gain.gain.exponentialRampToValueAtTime(0.001, t0 + dur);
                filter.type = 'lowpass';
                filter.frequency.setValueAtTime(freq * 2, t0);
                filter.frequency.exponentialRampToValueAtTime(200, t0 + dur);
                osc.connect(filter);
                filter.connect(gain);
                gain.connect(this.masterGain);
                osc.start(t0);
                osc.stop(t0 + dur + 0.05);
            }

            playTone(freq, duration, gainVal, type = 'square', fadeEnd = true) {
                if (!this.ctx || !this.initialized) return;
                const t0 = this.now();
                const dur = Math.min(duration, 1.5);
                const osc = this.ctx.createOscillator();
                const gain = this.ctx.createGain();
                osc.type = type;
                osc.frequency.setValueAtTime(freq, t0);
                gain.gain.setValueAtTime(gainVal, t0);
                if (fadeEnd) gain.gain.exponentialRampToValueAtTime(0.001, t0 + dur);
                else gain.gain.setValueAtTime(gainVal, t0 + dur);
                osc.connect(gain);
                gain.connect(this.masterGain);
                osc.start(t0);
                osc.stop(t0 + dur + 0.02);
            }

            gunshot(type) {
                const sounds = {
                    pistol: () => { this.playNoise(0.12, 800, 0.35, 'square', 200);
                        this.playNoise(0.08, 400, 0.25, 'sawtooth', 100); },
                    deagle: () => { this.playNoise(0.2, 600, 0.55, 'square', 150);
                        this.playNoise(0.15, 300, 0.4, 'sawtooth', 80); },
                    smg: () => { this.playNoise(0.09, 700, 0.25, 'square', 250);
                        this.playNoise(0.06, 500, 0.2, 'sawtooth', 150); },
                    rifle: () => { this.playNoise(0.15, 500, 0.45, 'square', 100);
                        this.playNoise(0.12, 350, 0.35, 'sawtooth', 60); },
                    sniper: () => { this.playNoise(0.3, 400, 0.6, 'square', 60);
                        this.playNoise(0.25, 250, 0.5, 'sawtooth', 40);
                        this.playTone(90, 0.2, 0.3, 'sine'); },
                    shotgun: () => { this.playNoise(0.22, 450, 0.55, 'square', 80);
                        this.playNoise(0.18, 300, 0.45, 'sawtooth', 50); },
                    slash: () => { this.playNoise(0.08, 1200, 0.2, 'sawtooth', 400); },
                    throw: () => { this.playNoise(0.12, 600, 0.15, 'sawtooth', 200); },
                };
                if (sounds[type]) sounds[type]();
            }
            explosion() {
                this.playNoise(0.6, 200, 0.7, 'sawtooth', 30);
                this.playNoise(0.4, 100, 0.5, 'square', 25);
                this.playTone(50, 0.5, 0.4, 'sine');
            }
            footstep(sneaking = false) {
                const g = sneaking ? 0.06 : 0.18;
                this.playNoise(0.06, 300, g, 'square', 150);
                this.playNoise(0.05, 200, g * 0.6, 'sawtooth', 100);
            }
            reload() {
                this.playTone(500, 0.06, 0.25);
                setTimeout(() => this.playTone(400, 0.06, 0.25), 300);
                setTimeout(() => this.playTone(600, 0.06, 0.25), 600);
            }
            plantBomb() {
                this.playTone(800, 0.08, 0.3, 'square');
                setTimeout(() => this.playTone(900, 0.08, 0.3, 'square'), 200);
                setTimeout(() => this.playTone(1000, 0.08, 0.3, 'square'), 400);
            }
            defuseBomb() {
                this.playTone(1000, 0.1, 0.3, 'square');
                setTimeout(() => this.playTone(800, 0.1, 0.3, 'square'), 150);
                setTimeout(() => this.playTone(600, 0.1, 0.3, 'square'), 300);
            }
            buySound() {
                this.playTone(700, 0.06, 0.25, 'square');
                setTimeout(() => this.playTone(900, 0.06, 0.25, 'square'), 80);
            }
            roundStart() {
                this.playTone(500, 0.12, 0.3, 'square');
                setTimeout(() => this.playTone(600, 0.12, 0.3, 'square'), 150);
                setTimeout(() => this.playTone(700, 0.12, 0.3, 'square'), 300);
            }
            roundEnd(win) {
                if (win) {
                    this.playTone(600, 0.15, 0.3, 'square');
                    setTimeout(() => this.playTone(800, 0.15, 0.3, 'square'), 180);
                    setTimeout(() => this.playTone(1000, 0.2, 0.3, 'square'), 360);
                } else {
                    this.playTone(400, 0.15, 0.3, 'square');
                    setTimeout(() => this.playTone(300, 0.15, 0.3, 'square'), 180);
                    setTimeout(() => this.playTone(200, 0.2, 0.3, 'square'), 360);
                }
            }
            hitSound() { this.playTone(1200, 0.04, 0.15, 'square'); }
            headshotSound() { this.playTone(1800, 0.08, 0.3, 'square');
                this.playTone(1200, 0.08, 0.25, 'square'); }
        }

