        function createDust2Map(scene) {
            const group = new THREE.Group();
            const colliders = [];
            const bombSites = [];
            const spawnPoints = { T: [], CT: [] };
            const coverPoints = [];
            const waypoints = [];

            const sandColor = 0xC2A670;
            const wallColor = 0xD4B896;
            const wallColor2 = 0xC9AD7F;
            const floorColor = 0xBBAA82;
            const woodColor = 0x8B7355;
            const crateColor = 0x9B8B6B;

            function addBox(x, y, z, w, h, d, color, isCollider = true, isFloor = false) {
                const geo = new THREE.BoxGeometry(w, h, d);
                const mat = new THREE.MeshLambertMaterial({ color, roughness: 0.85 });
                const mesh = new THREE.Mesh(geo, mat);
                mesh.position.set(x, y, z);
                mesh.receiveShadow = true;
                mesh.castShadow = true;
                group.add(mesh);
                if (isCollider) {
                    colliders.push({
                        min: { x: x - w / 2, y: y - h / 2, z: z - d / 2 },
                        max: { x: x + w / 2, y: y + h / 2, z: z + d / 2 },
                        type: isFloor ? 'floor' : 'wall',
                        oneWay: isFloor ? 'up' : null
                    });
                }
                return mesh;
            }

            function addCylinder(x, y, z, r, h, color, isCollider = true) {
                const geo = new THREE.CylinderGeometry(r, r, h, 16);
                const mat = new THREE.MeshLambertMaterial({ color, roughness: 0.85 });
                const mesh = new THREE.Mesh(geo, mat);
                mesh.position.set(x, y, z);
                group.add(mesh);
                if (isCollider) {
                    colliders.push({
                        min: { x: x - r, y: y - h / 2, z: z - r },
                        max: { x: x + r, y: y + h / 2, z: z + r },
                        type: 'cylinder',
                        radius: r,
                        centerX: x,
                        centerZ: z,
                        oneWay: null
                    });
                }
                return mesh;
            }

            // GROUND
            addBox(0, -0.5, 0, 180, 1, 140, floorColor, true, true);

            // === Dust2 Layout (X: East-West, Z: South-North) ===
            // T spawn at south (z ~ +50), CT spawn at north (z ~ -50)
            // A site at northeast (x ~ +30, z ~ -25)
            // B site at northwest (x ~ -30, z ~ -25)
            // Middle connects south to north at x ~ 0

