            const crateColor = 0x6B5B4A;

            function addBox(x, y, z, w, h, d, color, isCollider = true, isFloor = false) {
                const geo = new THREE.BoxGeometry(w, h, d);
                const mat = new THREE.MeshLambertMaterial({ color, roughness: 0.85 });
                const mesh = new THREE.Mesh(geo, mat);
                mesh.position.set(x, y, z);
                mesh.receiveShadow = true;
                mesh.castShadow = true;
                group.add(mesh);
                if (isCollider) {
                    colliders.push({
                        min: { x: x - w / 2, y: y - h / 2, z: z - d / 2 },
                        max: { x: x + w / 2, y: y + h / 2, z: z + d / 2 },
                        type: isFloor ? 'floor' : 'wall',
                        oneWay: isFloor ? 'up' : null
                    });
                }
                return mesh;
            }

            // Citadel layout: fortress with elevated positions
            addBox(0, -0.5, 0, 160, 1, 110, floorColor, true, true);
            addBox(80, 3.5, 0, 2, 8, 110, wallColor);
            addBox(-80, 3.5, 0, 2, 8, 110, wallColor);
