        // ============ PARTICLE/ EFFECT SYSTEM ============
        class EffectManager {
            constructor(scene) {
                this.scene = scene;
                this.particles = [];
                this.smokes = [];
                this.flames = [];
                this.shells = [];
            }
            addMuzzleFlash(pos, dir) {
                const light = new THREE.PointLight(0xffa500, 3, 5, 1.5);
                light.position.copy(pos);
                this.scene.add(light);
                setTimeout(() => this.scene.remove(light), 60);
                const geo = new THREE.SphereGeometry(0.12, 6, 6);
                const mat = new THREE.MeshBasicMaterial({ color: 0xffcc00, transparent: true, opacity: 0.9 });
                const flash = new THREE.Mesh(geo, mat);
                flash.position.copy(pos);
                flash.position.add(dir.clone().multiplyScalar(0.3));
                this.scene.add(flash);
                setTimeout(() => this.scene.remove(flash), 50);
            }
            addShell(pos, dir) {
                const geo = new THREE.CylinderGeometry(0.02, 0.02, 0.08, 6);
                const mat = new THREE.MeshLambertMaterial({ color: 0xCCAA66 });
                const shell = new THREE.Mesh(geo, mat);
                shell.position.copy(pos);
                shell.position.y -= 0.5;
                shell.velocity = new THREE.Vector3(
                    dir.x * 1.5 + (Math.random() - 0.5) * 2,
                    Math.random() * 3 + 2,
                    dir.z * 1.5 + (Math.random() - 0.5) * 2
                );
                shell.rotation.set(Math.random() * 3, Math.random() * 3, Math.random() * 3);
                this.scene.add(shell);
                this.shells.push({ mesh: shell, life: 2 });
            }
            addImpact(pos, normal, type = 'default') {
                const color = type === 'headshot' ? 0xff2222 : 0xcccccc;
                const geo = new THREE.SphereGeometry(0.04, 6, 6);
                const mat = new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.9 });
                const p = new THREE.Mesh(geo, mat);
                p.position.copy(pos);
                p.position.add(normal.clone().multiplyScalar(0.05));
                this.scene.add(p);
                setTimeout(() => this.scene.remove(p), 120);
            }
            addSmoke(pos, radius = 3) {
                const smokeGroup = new THREE.Group();
                for (let i = 0; i < 12; i++) {
                    const geo = new THREE.SphereGeometry(radius * 0.7, 8, 8);
                    const mat = new THREE.MeshLambertMaterial({
                        color: 0x999999,
                        transparent: true,
                        opacity: 0.45,
                        depthWrite: false
                    });
                    const s = new THREE.Mesh(geo, mat);
                    const angle = (i / 12) * Math.PI * 2;
                    s.position.set(Math.cos(angle) * radius * 0.6, Math.random() * radius * 0.5, Math.sin(angle) * radius * 0.6);
                    smokeGroup.add(s);
                }
                smokeGroup.position.copy(pos);
                smokeGroup.userData = { life: 15, maxLife: 15, radius };
                this.scene.add(smokeGroup);
                this.smokes.push(smokeGroup);
            }
            addFlame(pos, duration = 5) {
                const flameGroup = new THREE.Group();
                const geo = new THREE.ConeGeometry(0.5, 1.2, 8);
                const mat = new THREE.MeshBasicMaterial({ color: 0xff5500, transparent: true, opacity: 0.7 });
                const f1 = new THREE.Mesh(geo, mat);
                f1.position.y = 0.6;
                const f2 = new THREE.Mesh(geo.clone(), new THREE.MeshBasicMaterial({ color: 0xffaa00, transparent: true,
                    opacity: 0.5 }));
                f2.position.y = 0.4;
                f2.scale.set(0.7, 1, 0.7);
                const f3 = new THREE.Mesh(geo.clone(), new THREE.MeshBasicMaterial({ color: 0xff4400, transparent: true,
                    opacity: 0.6 }));
                f3.position.y = 0.8;
                f3.scale.set(0.5, 0.8, 0.5);
                flameGroup.add(f1);
                flameGroup.add(f2);
                flameGroup.add(f3);
                const light = new THREE.PointLight(0xff6600, 2, 6);
                light.position.y = 1;
                flameGroup.add(light);
                flameGroup.position.copy(pos);
                flameGroup.position.y = pos.y || 0;
                flameGroup.userData = { life: duration, maxLife: duration };
                this.scene.add(flameGroup);
                this.flames.push(flameGroup);
            }
            addBombPlanted(pos) {
                const geo = new THREE.BoxGeometry(0.4, 0.3, 0.3);
                const mat = new THREE.MeshLambertMaterial({ color: 0x333333 });
                const bomb = new THREE.Mesh(geo, mat);
                bomb.position.copy(pos);
                bomb.position.y += 0.15;
                const lightGeo = new THREE.SphereGeometry(0.06, 8, 8);
                const lightMat = new THREE.MeshBasicMaterial({ color: 0xff0000 });
                const light = new THREE.Mesh(lightGeo, lightMat);
                light.position.set(0.1, 0.1, 0.15);
                const light2 = new THREE.Mesh(lightGeo, new THREE.MeshBasicMaterial({ color: 0xff3333 }));
                light2.position.set(-0.1, 0, 0.15);
                bomb.add(light);
                bomb.add(light2);
                bomb.userData = { isBomb: true };
                this.scene.add(bomb);
                return bomb;
            }
            update(dt) {
                // Update shells
                for (let i = this.shells.length - 1; i >= 0; i--) {
                    const s = this.shells[i];
                    s.life -= dt;
                    s.mesh.velocity.y -= GRAVITY * dt;
                    s.mesh.position.add(s.mesh.velocity.clone().multiplyScalar(dt));
                    s.mesh.rotation.x += dt * 5;
                    s.mesh.rotation.z += dt * 3;
                    if (s.life <= 0 || s.mesh.position.y < -1) {
                        this.scene.remove(s.mesh);
                        this.shells.splice(i, 1);
                    }
                }
                // Update smoke
                for (let i = this.smokes.length - 1; i >= 0; i--) {
                    const s = this.smokes[i];
                    s.userData.life -= dt;
                    const ratio = s.userData.life / s.userData.maxLife;
                    s.children.forEach(child => {
                        if (child.material && child.material.transparent) {
                            child.material.opacity = 0.45 * Math.max(0, ratio);
                        }
                        if (child.position && Math.random() < 0.02) {
                            child.position.x += (Math.random() - 0.5) * 0.3;
                            child.position.z += (Math.random() - 0.5) * 0.3;
                        }
                    });
                    if (s.userData.life <= 0) {
                        this.scene.remove(s);
                        this.smokes.splice(i, 1);
                    }
                }
                // Update flames
                for (let i = this.flames.length - 1; i >= 0; i--) {
                    const f = this.flames[i];
                    f.userData.life -= dt;
                    if (f.userData.life <= 0) {
                        this.scene.remove(f);
                        this.flames.splice(i, 1);
                    }
                }
            }
        }

        // ============ PLAYER CLASS ============
        class Player {
            constructor({ id, name, team, position, isBot, difficulty, scene, game }) {
                this.id = id;
                this.name = name;
                this.team = team; // 'T' or 'CT'
                this.isBot = isBot;
                this.difficulty = difficulty || 'medium';
                this.scene = scene;
                this.game = game;
                this.position = new THREE.Vector3(position.x, 0.2, position.z);
                this.velocity = new THREE.Vector3();
                this.yaw = position.angle || 0;
                this.pitch = 0;
                this.health = MAX_HEALTH;
                this.armor = 0;
                this.hasHelmet = false;
                this.hasDefuseKit = false;
                this.money = 800;
                this.weapons = { 0: 'knife', 1: 'glock', 2: null, 3: null, 4: null, 5: {}, 6: {} };
                this.activeSlot = 1;
                this.magAmmo = {};
                this.reserveAmmo = {};
                this.reloading = false;
                this.reloadTimer = 0;
                this.fireCooldown = 0;
                this.kills = 0;
                this.deaths = 0;
                this.alive = true;
                this.crouched = false;
                this.sneaking = false;
                this.sprinting = false;
                this.onGround = false;
                this.jumpQueued = false;
                this.moving = false;
                this.lastFootstep = 0;
                this.flashBlindness = 0;
                this.scoped = false;
                this.isPlanting = false;
                this.isDefusing = false;
                this.plantTimer = 0;
                this.defuseTimer = 0;
                this.aimTarget = null;
                this.botAI = null;
                this.weaponMesh = null;
                this.shotBy = null;
                this.score = 0;
                this.mvps = 0;
                this.teamKills = 0;
                this.controlledBy = null; // For spectator
                this.initWeaponAmmo();
                this.createWeaponMesh();
                if (isBot) this.initBotAI();
            }

            initWeaponAmmo() {
                for (const [slot, wname] of Object.entries(this.weapons)) {
                    if (typeof wname === 'string' && WEAPONS[wname]) {
                        this.magAmmo[wname] = WEAPONS[wname].magSize;
                        this.reserveAmmo[wname] = WEAPONS[wname].reserveAmmo;
                    }
                }
            }

            createWeaponMesh() {
                if (this.weaponMesh) this.scene.remove(this.weaponMesh);
                const geo = new THREE.BoxGeometry(0.18, 0.18, 0.65);
                const mat = new THREE.MeshLambertMaterial({ color: 0x333333 });
                this.weaponMesh = new THREE.Mesh(geo, mat);
                this.weaponMesh.position.copy(this.position);
                this.weaponMesh.position.y += 1.3;
                this.scene.add(this.weaponMesh);
            }

            initBotAI() {
                this.botAI = new BotBrain(this, this.game);
            }

            getCurrentWeapon() {
                const wname = this.weapons[this.activeSlot];
                if (typeof wname === 'string') return WEAPONS[wname];
                return WEAPONS.knife;
            }

            getCurrentWeaponName() {
                return typeof this.weapons[this.activeSlot] === 'string' ? this.weapons[this.activeSlot] : 'knife';
            }

            getEyeHeight() {
                return this.crouched ? EYE_HEIGHT_CROUCH : EYE_HEIGHT_STAND;
            }

            getEyePosition() {
                return new THREE.Vector3(this.position.x, this.position.y + this.getEyeHeight(), this.position.z);
            }

            getForwardVector() {
                return new THREE.Vector3(-Math.sin(this.yaw), 0, -Math.cos(this.yaw));
            }

            getRightVector() {
                return new THREE.Vector3(Math.cos(this.yaw), 0, -Math.sin(this.yaw));
            }

            getAimDirection() {
                const forward = this.getForwardVector();
                const right = this.getRightVector();
                const pitchRad = this.pitch;
                const dir = new THREE.Vector3();
                dir.x = forward.x * Math.cos(pitchRad) + right.x * 0;
                dir.y = Math.sin(pitchRad);
                dir.z = forward.z * Math.cos(pitchRad) + right.z * 0;
                const horiz = Math.sqrt(dir.x * dir.x + dir.z * dir.z) || 1;
                dir.x = forward.x * Math.cos(pitchRad);
                dir.y = Math.sin(pitchRad);
                dir.z = forward.z * Math.cos(pitchRad);
                return dir.normalize();
            }

            equipWeapon(slot) {
                if (this.weapons[slot]) {
                    this.activeSlot = slot;
                    this.reloading = false;
                    this.reloadTimer = 0;
                    this.scoped = false;
                    const wname = this.weapons[slot];
                    if (typeof wname === 'string' && WEAPONS[wname]) {
                        this.updateWeaponMesh();
                    }
                    return true;
                }
                return false;
            }

            updateWeaponMesh() {
                if (this.weaponMesh) {
                    const wname = this.getCurrentWeaponName();
                    const colors = { knife: 0x888888, glock: 0x444444, usp: 0x333333, deagle: 0x555555, ak47: 0x8B5A2B,
                        m4a4: 0x2A3A2A, awp: 0x3A5A3A, scout: 0x4A4A3A, nova: 0x666666, xm1014: 0x555555, mp5: 0x3A3A3A,
                        p90: 0x4A4A4A };
                    this.weaponMesh.material.color.set(colors[wname] || 0x333333);
                }
            }

            takeDamage(amount, isHeadshot = false, attacker = null) {
                let damage = amount;
                if (this.armor > 0 && !isHeadshot) {
                    const absorbed = damage * 0.5;
                    const armorDamage = absorbed * 0.5;
                    this.armor = Math.max(0, this.armor - armorDamage);
                    damage = damage - absorbed;
                }
                if (this.armor > 0 && isHeadshot && this.hasHelmet) {
                    const absorbed = damage * 0.7;
                    this.armor = Math.max(0, this.armor - absorbed * 0.4);
                    damage = damage - absorbed;
                }
                this.health -= damage;
                if (attacker && attacker !== this) this.shotBy = attacker;
                if (this.health <= 0) {
                    this.health = 0;
                    this.die(attacker);
                }
                return Math.round(damage);
            }

            die(attacker) {
                if (!this.alive) return;
                this.alive = false;
                this.deaths++;
                if (attacker && attacker !== this) {
                    attacker.kills++;
                    attacker.money += 300;
                    attacker.score += 2;
                    if (attacker.team !== this.team && this.game) {
                        this.game.updateTeamScoresForKill();
                    }
                }
                this.dropWeapons();
                if (this.game) this.game.onPlayerDeath(this, attacker);
            }

            dropWeapons() {
                // Dropped weapons handled by game logic
            }

            respawn(position, angle) {
                this.alive = true;
                this.health = MAX_HEALTH;
                this.armor = 0;
                this.hasHelmet = false;
                this.hasDefuseKit = false;
                this.position.set(position.x, 0.2, position.z);
                this.yaw = angle;
                this.pitch = 0;
                this.velocity.set(0, 0, 0);
                this.crouched = false;
                this.sneaking = false;
                this.sprinting = false;
                this.flashBlindness = 0;
                this.scoped = false;
                this.isPlanting = false;
                this.isDefusing = false;
                this.plantTimer = 0;
                this.defuseTimer = 0;
                this.reloading = false;
                this.reloadTimer = 0;
                this.fireCooldown = 0;
                this.weapons = { 0: 'knife', 1: this.team === 'T' ? 'glock' : 'usp', 2: null, 3: null, 4: null, 5: {}, 6: {} };
                this.activeSlot = 1;
                this.initWeaponAmmo();
                if (this.weaponMesh) {
                    this.weaponMesh.position.copy(this.position);
                    this.weaponMesh.position.y += 1.3;
                }
            }

            canBuy() {
                return this.alive && this.game && this.game.phase === 'buy';
            }

            buyItem(itemName) {
                if (!this.canBuy()) return false;
                const item = WEAPONS[itemName];
                if (!item) return false;
                if (this.money < item.price) return false;
                if (item.category === 'gear') {
                    if (itemName === 'armor' && this.armor < MAX_ARMOR) {
                        this.money -= item.price;
                        this.armor = MAX_ARMOR;
                        audio.buySound();
                        return true;
                    }
                    if (itemName === 'helmet' && !this.hasHelmet && this.armor > 0) {
                        this.money -= item.price;
                        this.hasHelmet = true;
                        audio.buySound();
                        return true;
                    }
                    if (itemName === 'defusekit' && !this.hasDefuseKit && this.team === 'CT') {
                        this.money -= item.price;
                        this.hasDefuseKit = true;
                        audio.buySound();
                        return true;
                    }
                    return false;
                }
                if (item.category === 'grenade') {
                    if (this.weapons[5][itemName]) return false;
                    this.money -= item.price;
                    this.weapons[5][itemName] = true;
                    audio.buySound();
                    return true;
                }
                const slot = item.slot;
                if (slot === 0) return false;
                this.money -= item.price;
                this.weapons[slot] = itemName;
                this.magAmmo[itemName] = item.magSize;
                this.reserveAmmo[itemName] = item.reserveAmmo;
                this.activeSlot = slot;
                this.updateWeaponMesh();
                audio.buySound();
                return true;
            }

            hasWeapon(wname) {
                return Object.values(this.weapons).includes(wname) || this.weapons[5][wname];
            }

            startReload() {
                if (this.reloading) return;
                const wname = this.getCurrentWeaponName();
                const w = WEAPONS[wname];
                if (!w || w.magSize === 0) return;
                if (this.magAmmo[wname] >= w.magSize) return;
                if (this.reserveAmmo[wname] <= 0) return;
                this.reloading = true;
                this.reloadTimer = w.reloadTime;
                this.scoped = false;
                audio.reload();
            }

            updateReload(dt) {
                if (!this.reloading) return;
                this.reloadTimer -= dt;
                if (this.reloadTimer <= 0) {
                    const wname = this.getCurrentWeaponName();
                    const w = WEAPONS[wname];
                    const needed = w.magSize - this.magAmmo[wname];
                    const available = Math.min(needed, this.reserveAmmo[wname]);
                    this.magAmmo[wname] += available;
                    this.reserveAmmo[wname] -= available;
                    this.reloading = false;
                }
            }

            update(dt, game) {
                if (!this.alive) {
                    if (this.weaponMesh) this.weaponMesh.position.y = -999;
                    return;
                }
                this.updateReload(dt);
                if (this.fireCooldown > 0) this.fireCooldown -= dt;
                if (this.flashBlindness > 0) this.flashBlindness -= dt;
                if (this.isPlanting) {
                    this.plantTimer -= dt;
                    if (this.plantTimer <= 0) {
                        game.completePlant(this);
                        this.isPlanting = false;
                    }
                }
                if (this.isDefusing) {
                    this.defuseTimer -= dt;
                    if (this.defuseTimer <= 0) {
                        game.completeDefuse(this);
                        this.isDefusing = false;
                    }
                }
                if (this.weaponMesh && this.alive) {
                    const eye = this.getEyePosition();
                    this.weaponMesh.position.copy(eye);
                    this.weaponMesh.position.y -= 0.3;
                    const dir = this.getAimDirection();
                    this.weaponMesh.position.add(dir.clone().multiplyScalar(0.5));
                    this.weaponMesh.lookAt(eye.clone().add(dir));
                    if (this.crouched) this.weaponMesh.position.y += 0.2;
                }
                if (this.isBot && this.botAI) this.botAI.update(dt);
            }
        }

        // ============ BOT AI ============
        class BotBrain {
            constructor(player, game) {
                this.player = player;
                this.game = game;
                this.state = 'idle';
                this.targetWaypoint = null;
                this.currentWaypointIndex = 0;
                this.searchTimer = 0;
                this.reactionTimer = 0;
                this.shootTimer = 0;
                this.decisionTimer = 0;
                this.hasBomb = false;
                this.visibleEnemy = null;
                this.enemyLastSeen = null;
                this.enemyLastSeenTime = 0;
                this.stuckTimer = 0;
                this.lastStuckPos = null;
                this.botPath = [];
                this.pathIndex = 0;
                this.bombPlantTarget = null;
                this.defuseTarget = null;
                this.nadeTimer = 0;
                this.strafeDir = 0;
                this.strafeTimer = 0;
            }

            getDifficultyParams() {
                const d = this.player.difficulty;
                if (d === 'easy') return { reaction: 0.6, aimError: 0.12, moveSpeed: 0.8, tactical: 0.3, nadeChance: 0.1,
                    interval: 0.4 };
                if (d === 'hard') return { reaction: 0.12, aimError: 0.02, moveSpeed: 1.1, tactical: 0.85, nadeChance: 0.7,
                    interval: 0.28 };
                return { reaction: 0.3, aimError: 0.06, moveSpeed: 1.0, tactical: 0.55, nadeChance: 0.35, interval: 0.32 };
            }

            update(dt) {
                const p = this.player;
                if (!p.alive || !this.game || this.game.phase !== 'live') return;
                const params = this.getDifficultyParams();
                this.decisionTimer -= dt;
                if (this.decisionTimer <= 0) {
                    this.decisionTimer = 0.15 + Math.random() * 0.3;
                    this.makeDecision();
                }
                // Find visible enemy
                this.visibleEnemy = this.findVisibleEnemy();
                if (this.visibleEnemy) {
                    this.enemyLastSeen = this.visibleEnemy.position.clone();
                    this.enemyLastSeenTime = this.game.time;
                    this.state = 'combat';
                } else if (this.state === 'combat') {
                    if (this.game.time - this.enemyLastSeenTime > 1.5) {
                        this.state = 'search';
                        this.searchTimer = 3 + Math.random() * 4;
                    }
                }
                if (this.state === 'combat') {
                    this.combatUpdate(dt, params);
                } else if (this.state === 'search') {
                    this.searchUpdate(dt, params);
                } else {
                    this.navigateUpdate(dt, params);
                }
                // Throw grenades occasionally in combat
                if (this.state === 'combat' && this.nadeTimer <= 0 && Math.random() < 0.01) {
                    this.throwGrenade();
                    this.nadeTimer = 5 + Math.random() * 8;
                }
                if (this.nadeTimer > 0) this.nadeTimer -= dt;
            }

            findVisibleEnemy() {
                const p = this.player;
                const enemies = this.game.players.filter(e => e.alive && e.team !== p.team);
                let closest = null;
                let minDist = 80;
                for (const enemy of enemies) {
                    const dist = p.position.distanceTo(enemy.position);
                    if (dist > minDist) continue;
                    const dir = enemy.getEyePosition().sub(p.getEyePosition()).normalize();
                    const aimDir = p.getAimDirection();
                    const dot = dir.dot(aimDir);
                    if (dot > 0.25) {
                        if (!this.game.raycastBlocked(p.getEyePosition(), enemy.getEyePosition(), p.id)) {
                            closest = enemy;
                            minDist = dist;
                        }
                    }
                }
                return closest;
            }

            combatUpdate(dt, params) {
                const p = this.player;
                const enemy = this.visibleEnemy;
                if (!enemy) return;
                // Aim at enemy
                const eye = p.getEyePosition();
                const targetEye = enemy.getEyePosition();
                const dir = targetEye.sub(eye).normalize();
                const targetYaw = Math.atan2(-dir.x, -dir.z);
                const targetPitch = Math.asin(Math.max(-0.7, Math.min(0.7, dir.y)));
                // Apply aim error based on difficulty
                const errX = (Math.random() - 0.5) * params.aimError * 2;
                const errY = (Math.random() - 0.5) * params.aimError * 2;
                // Smooth aim
                const lerpSpeed = params.difficulty === 'hard' ? 12 : params.difficulty === 'easy' ? 3 : 7;
                p.yaw += ((targetYaw + errX) - p.yaw) * Math.min(1, lerpSpeed * dt);
                p.pitch += ((targetPitch + errY) - p.pitch) * Math.min(1, lerpSpeed * dt);
                p.pitch = Math.max(-1.2, Math.min(1.2, p.pitch));
                // Movement: strafe and approach
                const dist = p.position.distanceTo(enemy.position);
                this.strafeTimer -= dt;
                if (this.strafeTimer <= 0) {
                    this.strafeDir = Math.random() > 0.5 ? 1 : -1;
                    this.strafeTimer = 0.4 + Math.random() * 0.8;
                }
                // Shoot
                this.shootTimer -= dt;
                const weapon = p.getCurrentWeapon();
                const distPenalty = dist > 30 && weapon.damageDrop > 0.1 ? 0.5 : 1;
                const aimScore = Math.random() * params.aimError * 10;
                const threshold = params.aimError * 2 + (dist > 40 ? 0.03 : 0);
                if (this.shootTimer <= 0 && aimScore > threshold * distPenalty) {
                    this.shootTimer = weapon.fireRate * (1 + Math.random() * 0.3);
                    this.shootAt(enemy);
                }
            }

            shootAt(enemy) {
                const p = this.player;
                const weapon = p.getCurrentWeapon();
                if (!weapon || weapon.magSize === 0) return;
                if (p.magAmmo[p.getCurrentWeaponName()] <= 0) {
                    if (p.reserveAmmo[p.getCurrentWeaponName()] > 0) p.startReload();
                    return;
                }
                p.fireCooldown = weapon.fireRate;
                const dir = p.getAimDirection();
                const spread = weapon.spread * (p.moving ? 2.5 : 1);
                const spreadX = (Math.random() - 0.5) * spread * 4;
                const spreadY = (Math.random() - 0.5) * spread * 4;
                const shootDir = dir.clone();
                const right = p.getRightVector();
                shootDir.add(right.clone().multiplyScalar(spreadX));
                shootDir.y += spreadY;
                shootDir.normalize();
                this.game.handleShot(p, shootDir, p.getEyePosition());
            }

            searchUpdate(dt, params) {
                const p = this.player;
                this.searchTimer -= dt;
                if (this.searchTimer <= 0) {
                    this.state = 'navigate';
                    this.selectWaypoint();
                }
                // Move toward last seen enemy
                if (this.enemyLastSeen) {
                    this.moveToward(this.enemyLastSeen, params);
                    if (p.position.distanceTo(this.enemyLastSeen) < 2) {
                        this.searchTimer = 0;
                    }
                }
            }

            navigateUpdate(dt, params) {
                const p = this.player;
                // Navigate to waypoint
                if (this.botPath.length === 0) {
                    this.selectWaypoint();
                }
                if (this.botPath.length > 0 && this.pathIndex < this.botPath.length) {
                    const wp = this.botPath[this.pathIndex];
                    const dist = p.position.distanceTo(new THREE.Vector3(wp.x, p.position.y, wp.z));
                    if (dist < 1.5) {
                        this.pathIndex++;
                    } else {
                        this.moveToward(new THREE.Vector3(wp.x, p.position.y, wp.z), params);
                    }
                }
                if (this.pathIndex >= this.botPath.length || this.botPath.length === 0) {
                    this.selectWaypoint();
                }
                // Check stuck
                if (this.lastStuckPos) {
                    const moved = p.position.distanceTo(this.lastStuckPos);
                    if (moved < 0.3) {
                        this.stuckTimer += dt;
                        if (this.stuckTimer > 1.5) {
                            this.selectWaypoint();
                            this.stuckTimer = 0;
                        }
                    } else {
                        this.stuckTimer = 0;
                    }
                }
                this.lastStuckPos = p.position.clone();
            }

            moveToward(target, params) {
                const p = this.player;
                const dx = target.x - p.position.x;
                const dz = target.z - p.position.z;
                const dist = Math.sqrt(dx * dx + dz * dz);
                if (dist < 1) return;
                const targetYaw = Math.atan2(-dx, -dz);
                const yawDiff = ((targetYaw - p.yaw + Math.PI * 3) % (Math.PI * 2)) - Math.PI;
                p.yaw += yawDiff * Math.min(1, 5 * 0.016);
                // Move forward
                const forward = p.getForwardVector();
                const moveSpeed = p.crouched ? CROUCH_SPEED : (p.sneaking ? SNEAK_SPEED : RUN_SPEED);
                const vel = forward.multiplyScalar(moveSpeed * params.moveSpeed);
                p.velocity.x = vel.x;
                p.velocity.z = vel.z;
                p.moving = true;
            }

            selectWaypoint() {
                const p = this.player;
                const mapData = this.game.mapData;
                if (!mapData || !mapData.waypoints) return;
                this.botPath = [];
                this.pathIndex = 0;
                // Choose behavior based on situation
                const bombPlanted = this.game.bombPlanted;
                const bombCarrier = this.game.bombCarrier;
                if (p.team === 'T') {
                    if (bombPlanted) {
                        // Defend bomb
                        const bombPos = this.game.bombPosition;
                        this.botPath = [{ x: bombPos.x, z: bombPos.z }];
                        return;
                    }
                    if (bombCarrier === p) {
                        // Go to bomb site
                        const sites = this.game.bombSites;
                        const target = sites[Math.floor(Math.random() * sites.length)];
                        this.botPath = this.getPathTo(target);
                        this.hasBomb = true;
                        return;
                    }
                    // Attack: go to random bomb site or mid
                    const r = Math.random();
                    if (r < 0.35) this.botPath = this.getPathTo(this.game.bombSites[0]);
                    else if (r < 0.7) this.botPath = this.getPathTo(this.game.bombSites[1]);
                    else this.botPath = this.getPathTo({ x: 0, z: 0 });
                } else {
                    // CT
                    if (bombPlanted) {
                        const bombPos = this.game.bombPosition;
                        this.botPath = [{ x: bombPos.x, z: bombPos.z }];
                        return;
                    }
                    // Defend sites
                    const siteIndex = p.id % 2;
                    const sites = this.game.bombSites;
                    if (sites[siteIndex]) {
                        const site = sites[siteIndex];
                        const patrolPos = {
                            x: site.x + (Math.random() - 0.5) * 8,
                            z: site.z + (Math.random() - 0.5) * 8
                        };
                        this.botPath = this.getPathTo(patrolPos);
                    }
                }
            }

            getPathTo(target) {
                const mapData = this.game.mapData;
                if (!mapData || !mapData.waypoints) return [{ x: target.x, z: target.z }];
                const path = [];
                // Simple path: go to nearest waypoint, then to target
                path.push({ x: target.x, z: target.z });
                return path;
            }

            throwGrenade() {
                const p = this.player;
                if (p.weapons[5] && p.weapons[5]['hegrenade'] && this.enemyLastSeen) {
                    p.weapons[5]['hegrenade'] = false;
                    const dir = this.enemyLastSeen.clone().sub(p.getEyePosition()).normalize();
                    this.game.throwGrenade(p, 'hegrenade', dir);
                } else if (p.weapons[5] && p.weapons[5]['flashbang'] && this.visibleEnemy) {
                    p.weapons[5]['flashbang'] = false;
                    const dir = this.visibleEnemy.getEyePosition().sub(p.getEyePosition()).normalize();
                    this.game.throwGrenade(p, 'flashbang', dir);
                }
            }
        }

        // ============ MAIN GAME CLASS ============
        class Game {
            constructor() {
                this.scene = null;
                this.camera = null;
                this.renderer = null;
                this.clock = new THREE.Clock();
                this.players = [];
                this.localPlayer = null;
                this.mapData = null;
                this.effects = null;
                this.phase = 'menu';
                this.roundNumber = 0;
                this.maxRounds = 12;
                this.score = { T: 0, CT: 0 };
                this.roundTimer = ROUND_TIME;
                this.buyTimer = BUY_TIME;
                this.bombPlanted = false;
                this.bombPosition = null;
                this.bombTimer = BOMB_TIMER;
                this.bombCarrier = null;
                this.bombMesh = null;
                this.roundEndTimer = 0;
                this.roundEndReason = '';
                this.mapName = 'de_dust2';
                this.localTeam = 'CT';
                this.botCount = 8;
                this.difficulty = 'medium';
                this.input = { forward: false, back: false, left: false, right: false, jump: false, crouch: false,
                    sneak: false, sprint: false, primary: false, secondary: false, reload: false, buy: false,
                interact: false, slot1: false, slot2: false, slot3: false, slot4: false, slot5: false, slot0: false,
                    throwGrenade: false };
                this.keys = {};
                this.mouseDown = { left: false, right: false };
                this.mouseMove = { x: 0, y: 0 };
                this.spectatorIndex = 0;
                this.buyMenuVisible = false;
                this.scoreboardVisible = false;
                this.fireCooldownTimer = 0;
                this.plantedBombMesh = null;
                this.winnerTeam = null;
                this.gameOver = false;
                this.flashOverlayEl = document.getElementById('flash-overlay');
                this.hitmarkerEl = document.getElementById('hitmarker');
                this.bombSites = [];
                this.init();
            }

            init() {
                // Scene
                this.scene = new THREE.Scene();
                this.scene.background = new THREE.Color(0x87CEEB);
                this.scene.fog = new THREE.Fog(0x87CEEB, 50, 180);

                // Camera
                this.camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.05, 300);
                this.camera.position.set(0, 2, 10);

                // Renderer
                this.renderer = new THREE.WebGLRenderer({ antialias: true });
                this.renderer.setSize(window.innerWidth, window.innerHeight);
                this.renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
                this.renderer.shadowMap.enabled = true;
                this.renderer.shadowMap.type = THREE.PCFSoftShadowMap;
                this.renderer.toneMapping = THREE.ACESFilmicToneMapping;
                this.renderer.toneMappingExposure = 1.0;
                document.body.prepend(this.renderer.domElement);

                // Lights
                const ambient = new THREE.AmbientLight(0x8899AA, 0.7);
                this.scene.add(ambient);
                const sun = new THREE.DirectionalLight(0xFFEECC, 1.4);
                sun.position.set(40, 80, 30);
                sun.castShadow = true;
                sun.shadow.mapSize.width = 2048;
                sun.shadow.mapSize.height = 2048;
                sun.shadow.camera.near = 0.5;
                sun.shadow.camera.far = 300;
                sun.shadow.camera.left = -100;
                sun.shadow.camera.right = 100;
                sun.shadow.camera.top = 100;
                sun.shadow.camera.bottom = -100;
                sun.shadow.bias = -0.0005;
                this.scene.add(sun);

                this.effects = new EffectManager(this.scene);

                this.setupEventListeners();
                this.setupMenuListeners();
                this.updateHUD();
                this.renderLoop();
            }

            setupEventListeners() {
                const canvas = this.renderer.domElement;
                document.addEventListener('keydown', (e) => {
                    if (this.phase === 'menu') return;
                    if (e.repeat) return;
                    this.keys[e.code] = true;
                    if (e.code === 'KeyW') this.input.forward = true;
                    if (e.code === 'KeyS') this.input.back = true;
                    if (e.code === 'KeyA') this.input.left = true;
                    if (e.code === 'KeyD') this.input.right = true;
                    if (e.code === 'Space') { e.preventDefault();
                        this.input.jump = true; }
                    if (e.code === 'ShiftLeft' || e.code === 'ShiftRight') this.input.sneak = true;
                    if (e.code === 'ControlLeft') this.input.crouch = true;
                    if (e.code === 'KeyR') this.input.reload = true;
                    if (e.code === 'KeyB') this.toggleBuyMenu();
                    if (e.code === 'Tab') { e.preventDefault();
                        this.toggleScoreboard(); }
                    if (e.code === 'Digit1') this.equipLocalSlot(1);
                    if (e.code === 'Digit2') this.equipLocalSlot(2);
                    if (e.code === 'Digit3') this.equipLocalSlot(3);
                    if (e.code === 'Digit4') this.equipLocalSlot(4);
                    if (e.code === 'Digit5') this.equipLocalSlot(5);
                    if (e.code === 'KeyG') this.throwLocalGrenade();
                    if (e.code === 'KeyE') this.tryInteract();
                    if (e.code === 'KeyF') this.tryInteract();
                    if (e.code === 'KeyM') this.muteAudio();
                });
                document.addEventListener('keyup', (e) => {
                    this.keys[e.code] = false;
                    if (e.code === 'KeyW') this.input.forward = false;
                    if (e.code === 'KeyS') this.input.back = false;
                    if (e.code === 'KeyA') this.input.left = false;
                    if (e.code === 'KeyD') this.input.right = false;
                    if (e.code === 'Space') this.input.jump = false;
                    if (e.code === 'ShiftLeft' || e.code === 'ShiftRight') this.input.sneak = false;
                    if (e.code === 'ControlLeft') this.input.crouch = false;
                    if (e.code === 'KeyR') this.input.reload = false;
                    if (e.code === 'Tab') this.toggleScoreboard();
                });
                canvas.addEventListener('mousedown', (e) => {
                    if (this.phase === 'menu') return;
                    audio.resume();
                    if (e.button === 0) { this.mouseDown.left = true;
                        this.input.primary = true; }
                    if (e.button === 2) { this.mouseDown.right = true;
                        this.input.secondary = true; }
                });
                canvas.addEventListener('mouseup', (e) => {
                    if (e.button === 0) { this.mouseDown.left = false;
                        this.input.primary = false; }
                    if (e.button === 2) { this.mouseDown.right = false;
                        this.input.secondary = false; }
                });
                canvas.addEventListener('mousemove', (e) => {
                    if (this.phase === 'menu') return;
                    if (document.pointerLockElement === canvas) {
                        this.mouseMove.x += e.movementX;
                        this.mouseMove.y += e.movementY;
                    }
                });
                canvas.addEventListener('contextmenu', (e) => e.preventDefault());
                canvas.addEventListener('click', () => {
                    if (this.phase !== 'menu' && document.pointerLockElement !== canvas) {
                        canvas.requestPointerLock();
                    }
                    audio.resume();
                });
                canvas.requestPointerLock = canvas.requestPointerLock || canvas.mozRequestPointerLock || canvas
                    .webkitRequestPointerLock;
                window.addEventListener('resize', () => {
                    this.camera.aspect = window.innerWidth / window.innerHeight;
                    this.camera.updateProjectionMatrix();
                    this.renderer.setSize(window.innerWidth, window.innerHeight);
                });
            }

            setupMenuListeners() {
                const btnStart = document.getElementById('btn-start');
                btnStart.addEventListener('click', () => {
                    this.mapName = document.getElementById('menu-map').value;
                    const teamSel = document.getElementById('menu-team').value;
                    this.localTeam = teamSel === 'random' ? (Math.random() > 0.5 ? 'CT' : 'T') : teamSel;
                    this.botCount = parseInt(document.getElementById('menu-bots').value);
                    this.difficulty = document.getElementById('menu-difficulty').value;
                    this.maxRounds = parseInt(document.getElementById('menu-rounds').value);
                    this.startGame();
                });
            }

            startGame() {
                document.getElementById('menu-screen').style.display = 'none';
                this.loadMap(this.mapName);
                this.phase = 'buy';
                this.roundNumber = 0;
                this.score = { T: 0, CT: 0 };
                this.gameOver = false;
                this.spawnAllPlayers();
                this.startRound();
                this.camera.rotation.set(0, 0, 0);
                if (this.renderer.domElement.requestPointerLock) {
                    this.renderer.domElement.requestPointerLock();
                }
                audio.resume();
            }

            loadMap(mapName) {
                // Remove old map
                if (this.mapData) {
                    this.scene.remove(this.mapData.group);
                }
                // Remove old players
                for (const p of this.players) {
                    if (p.weaponMesh) this.scene.remove(p.weaponMesh);
                }
                this.players = [];
                // Remove bomb mesh
                if (this.plantedBombMesh) this.scene.remove(this.plantedBombMesh);

                if (mapName === 'de_dust2') this.mapData = createDust2Map(this.scene);
                else if (mapName === 'de_warehouse') this.mapData = createWarehouseMap(this.scene);
                else if (mapName === 'de_citadel') this.mapData = createCitadelMap(this.scene);
                else this.mapData = createDust2Map(this.scene);
                this.bombSites = this.mapData.bombSites;
                this.plantedBombMesh = null;
            }

            spawnAllPlayers() {
                const teamSize = Math.floor(this.botCount / 2);
                const humanTeam = this.localTeam;
                const enemyTeam = humanTeam === 'T' ? 'CT' : 'T';
                const totalT = humanTeam === 'T' ? teamSize + 1 : teamSize;
                const totalCT = enemyTeam === 'CT' ? teamSize + 1 : teamSize;
                const tSpawns = this.mapData.spawnPoints.T;
                const ctSpawns = this.mapData.spawnPoints.CT;
                let tIdx = 0,
                    ctIdx = 0;
                // Create local player
                const localSpawn = (humanTeam === 'T' ? tSpawns : ctSpawns)[0];
                this.localPlayer = new Player({
                    id: 0,
                    name: '你',
                    team: humanTeam,
                    position: { x: localSpawn.x, z: localSpawn.z, angle: localSpawn.angle },
                    isBot: false,
                    difficulty: this.difficulty,
                    scene: this.scene,
                    game: this
                });
                this.players.push(this.localPlayer);
                if (humanTeam === 'T') tIdx++;
                else ctIdx++;
                // Create bots
                for (let i = 0; i < totalT; i++) {
                    const sp = tSpawns[tIdx++ % tSpawns.length];
                    const bot = new Player({
                        id: i + 1,
                        name: `T-${i + 1}`,
                        team: 'T',
                        position: { x: sp.x + (Math.random() - 0.5) * 4, z: sp.z, angle: sp.angle },
                        isBot: true,
                        difficulty: this.difficulty,
                        scene: this.scene,
                        game: this
                    });
                    this.players.push(bot);
                }
                for (let i = 0; i < totalCT; i++) {
                    const sp = ctSpawns[ctIdx++ % ctSpawns.length];
                    const bot = new Player({
                        id: i + totalT + 2,
                        name: `CT-${i + 1}`,
                        team: 'CT',
                        position: { x: sp.x + (Math.random() - 0.5) * 4, z: sp.z, angle: sp.angle },
                        isBot: true,
                        difficulty: this.difficulty,
                        scene: this.scene,
                        game: this
                    });
                    this.players.push(bot);
                }
            }

            startRound() {
                this.roundNumber++;
                this.phase = 'buy';
                this.buyTimer = BUY_TIME;
                this.roundTimer = ROUND_TIME;
                this.bombPlanted = false;
                this.bombPosition = null;
                this.bombTimer = BOMB_TIMER;
                this.bombCarrier = null;
                this.winnerTeam = null;
                this.roundEndTimer = 0;
                this.spectatorIndex = 0;
                this.hideBuyMenu();
                this.hideScoreboard();
                // Find bomb carrier (one T player)
                const tPlayers = this.players.filter(p => p.team === 'T' && p.alive);
                if (tPlayers.length > 0) {
                    this.bombCarrier = tPlayers[Math.floor(Math.random() * tPlayers.length)];
                }
                // Reset player states
                const tSpawns = this.mapData.spawnPoints.T;
                const ctSpawns = this.mapData.spawnPoints.CT;
                let tIdx = 0,
                    ctIdx = 0;
                for (const p of this.players) {
                    const sp = p.team === 'T' ? tSpawns[tIdx++ % tSpawns.length] : ctSpawns[ctIdx++ % ctSpawns.length];
                    p.respawn({ x: sp.x, z: sp.z, angle: sp.angle }, sp.angle);
                    // Give round start money
                    if (this.roundNumber === 1) {
                        p.money = 800;
                    } else {
                        const prevRoundWinner = this.winnerTeam;
                        const won = prevRoundWinner === p.team || !prevRoundWinner;
                        const baseMoney = won ? 3250 : 1400 + Math.min(2000, (this.roundNumber - 1) * 500);
                        p.money += baseMoney;
                    }
                    // Economy cap
                    p.money = Math.min(p.money, 16000);
                }
                // Simple AI buying for bots
                for (const p of this.players) {
                    if (p.isBot && p.alive) this.botBuy(p);
                }
                // Local player auto-buys basic if first round
                if (this.roundNumber === 1 && this.localPlayer.alive) {
                    // Auto equipment for first round (tutorial)
                }
                audio.roundStart();
                this.updateHUD();
                this.showNotice(`第 ${this.roundNumber} 回合 - 购买阶段`, '#e8b830');
            }

            botBuy(p) {
                if (!p.alive || p.money < 200) return;
                const team = p.team;
                const isFirstRound = this.roundNumber === 1;
                if (isFirstRound) {
                    if (team === 'T') p.buyItem('glock');
                    else p.buyItem('usp');
                    p.buyItem('armor');
                    return;
                }
                // Strategy based on money
                if (p.money > 4000 + Math.random() * 2000) {
                    p.buyItem('armor');
                    p.buyItem('helmet');
                    if (team === 'T') p.buyItem('ak47');
                    else p.buyItem('m4a4');
                    if (Math.random() > 0.5) p.buyItem('smokegrenade');
                    if (Math.random() > 0.5) p.buyItem('hegrenade');
                    if (Math.random() > 0.3) p.buyItem('flashbang');
                } else if (p.money > 2000 + Math.random() * 1000) {
                    p.buyItem('armor');
                    if (team === 'T') p.buyItem('mp5');
                    else p.buyItem('mp5');
                    if (Math.random() > 0.5) p.buyItem('hegrenade');
                } else if (p.money > 800) {
                    p.buyItem('armor');
                    if (team === 'T') p.buyItem('glock');
                    else p.buyItem('usp');
                }
            }

            // ============ GAME LOOP ============
            renderLoop() {
                requestAnimationFrame(() => this.renderLoop());
                const dt = Math.min(this.clock.getDelta(), 0.1);
                this.update(dt);
                this.renderer.render(this.scene, this.camera);
            }

            update(dt) {
                this.effects.update(dt);

                // Update players
                for (const p of this.players) {
                    p.update(dt, this);
                    if (p.alive) this.updatePlayerPhysics(p, dt);
                    if (p.isBot && p.alive) this.updateBotFire(p, dt);
                }

                // Update local player controls
                if (this.phase === 'live' && this.localPlayer && this.localPlayer.alive) {
                    this.updateLocalControls(dt);
                }

                // Phase logic
                if (this.phase === 'buy') {
                    this.buyTimer -= dt;
                    if (this.buyTimer <= 0) {
                        this.phase = 'live';
                        audio.buySound();
                        this.showNotice('回合开始!', '#3dd84a');
                    }
                } else if (this.phase === 'live') {
                    this.roundTimer -= dt;
                    if (this.bombPlanted) {
                        this.bombTimer -= dt;
                        if (this.bombTimer <= 0) {
                            this.bombTimer = 0;
                            this.endRound('T', '炸弹爆炸');
                        }
                    }
                    if (this.roundTimer <= 0) {
                        this.roundTimer = 0;
                        if (!this.bombPlanted) this.endRound('CT', '时间耗尽');
                    }
                    // Check for TS alive
                    const aliveT = this.players.filter(p => p.team === 'T' && p.alive);
                    const aliveCT = this.players.filter(p => p.team === 'CT' && p.alive);
                    if (aliveT.length === 0 && !this.bombPlanted) {
                        this.endRound('CT', '消灭所有恐怖分子');
                    } else if (aliveCT.length === 0) {
                        this.endRound('T', '消灭所有反恐精英');
                    }
                    // Auto plant/defuse for bots
                    this.updateBotObjectives(dt);
                } else if (this.phase === 'round_end') {
                    this.roundEndTimer -= dt;
                    if (this.roundEndTimer <= 0) {
                        const totalRounds = this.maxRounds * 2;
                        if (this.roundNumber >= totalRounds) {
                            this.endGame();
                        } else {
                            this.startRound();
                        }
                    }
                }

                this.updateHUD();
                this.updateRadar();
                this.updateFlashOverlay();
                this.updateSpectatorIfNeeded();
            }

            updatePlayerPhysics(p, dt) {
                // Gravity
                p.velocity.y -= GRAVITY * dt;
                if (p.velocity.y < -20) p.velocity.y = -20;
                const newPos = p.position.clone();
                newPos.add(p.velocity.clone().multiplyScalar(dt));
                // Collision detection
                const collider = this.checkCollisions(p, newPos);
                if (collider) {
                    if (collider.type === 'floor' || collider.oneWay === 'up') {
                        if (p.velocity.y < 0) {
                            p.position.y = collider.max.y + 0.01;
                            p.velocity.y = 0;
                            p.onGround = true;
                        }
                    } else {
                        // Block horizontal movement
                        const back = p.velocity.clone().multiplyScalar(-0.5);
                        p.velocity.x = back.x;
                        p.velocity.z = back.z;
                    }
                } else {
                    p.position.copy(newPos);
                    if (p.position.y < -5) p.position.y = -5;
                    p.onGround = false;
                }
                // Check floor collision
                const belowPos = p.position.clone();
                belowPos.y -= 0.2;
                const belowCollider = this.checkCollisionsAt(p, belowPos);
                if (belowCollider && belowCollider.type === 'floor') {
                    p.onGround = true;
                    if (p.velocity.y < 0) {
                        p.velocity.y = 0;
                        p.position.y = belowCollider.max.y + 0.01;
                    }
                }
                // Footstep sounds
                if (p.onGround && p.moving && p.alive) {
                    const stepInterval = p.sneaking || p.crouched ? 0.55 : 0.3;
                    p.lastFootstep += dt;
                    if (p.lastFootstep > stepInterval) {
                        p.lastFootstep = 0;
                        const isLocal = p === this.localPlayer;
                        const dist = isLocal ? 0 : this.camera.position.distanceTo(p.position);
                        if (!isLocal && dist < 20) audio.footstep(p.sneaking || p.crouched);
                        else if (isLocal) audio.footstep(p.sneaking || p.crouched);
                    }
                }
            }

            checkCollisions(p, pos) {
                const colliders = this.mapData?.colliders || [];
                const radius = PLAYER_RADIUS;
                const height = p.crouched ? 1.2 : PLAYER_HEIGHT;
                for (const c of colliders) {
                    if (c.type === 'cylinder') {
                        const dx = pos.x - c.centerX;
                        const dz = pos.z - c.centerZ;
                        const dist = Math.sqrt(dx * dx + dz * dz);
                        if (dist < c.radius + radius) return c;
                        continue;
                    }
                    const minX = c.min.x - radius;
                    const maxX = c.max.x + radius;
                    const minZ = c.min.z - radius;
                    const maxZ = c.max.z + radius;
                    const minY = c.min.y;
                    const maxY = c.max.y;
                    if (pos.x > minX && pos.x < maxX &&
                        pos.z > minZ && pos.z < maxZ &&
                        pos.y + 0.3 > minY && pos.y < maxY) {
                        return c;
                    }
                }
                return null;
            }

            checkCollisionsAt(p, pos) {
                const colliders = this.mapData?.colliders || [];
                for (const c of colliders) {
                    if (c.type === 'cylinder') {
                        const dx = pos.x - c.centerX;
                        const dz = pos.z - c.centerZ;
                        if (Math.sqrt(dx * dx + dz * dz) < c.radius) return c;
                        continue;
                    }
                    if (pos.x > c.min.x && pos.x < c.max.x &&
                        pos.y > c.min.y && pos.y < c.max.y &&
                        pos.z > c.min.z && pos.z < c.max.z) {
                        return c;
                    }
                }
                return null;
            }

            raycastBlocked(from, to, excludeId = null) {
                const dir = to.sub(from);
                const dist = dir.length();
                const rayDir = dir.normalize();
                const colliders = this.mapData?.colliders || [];
                for (const c of colliders) {
                    if (c.type === 'cylinder') {
                        // Simple AABB vs ray
                        const min = { x: c.centerX - c.radius, y: c.min.y, z: c.centerZ - c.radius };
                        const max = { x: c.centerX + c.radius, y: c.max.y, z: c.centerZ + c.radius };
                        const t = this.rayAABBIntersect(from, rayDir, min, max);
                        if (t && t < dist) return true;
                        continue;
                    }
                    const t = this.rayAABBIntersect(from, rayDir, c.min, c.max);
                    if (t && t < dist) return true;
                }
                // Check player blocking (simplified - ignore for now)
                return false;
            }

            rayAABBIntersect(origin, dir, min, max) {
                let tmin = 0;
                let tmax = Infinity;
                const axes = ['x', 'y', 'z'];
                for (const axis of axes) {
                    const o = origin[axis];
                    const d = dir[axis];
                    if (Math.abs(d) < 0.0001) {
                        if (o < min[axis] || o > max[axis]) return null;
                    } else {
                        let t1 = (min[axis] - o) / d;
                        let t2 = (max[axis] - o) / d;
                        if (t1 > t2)[t1, t2] = [t2, t1];
                        if (t1 > tmin) tmin = t1;
                        if (t2 < tmax) tmax = t2;
                        if (tmin > tmax) return null;
                    }
                }
                return tmin;
            }

            raycastHitTest(origin, dir, maxDist = 100, excludeId = null) {
                let bestHit = null;
                let bestDist = maxDist;
                // Check colliders
                const colliders = this.mapData?.colliders || [];
                for (const c of colliders) {
                    if (c.type === 'cylinder') {
                        const min = { x: c.centerX - c.radius, y: c.min.y, z: c.centerZ - c.radius };
                        const max = { x: c.centerX + c.radius, y: c.max.y, z: c.centerZ + c.radius };
                        const t = this.rayAABBIntersect(origin, dir, min, max);
                        if (t && t < bestDist) {
                            bestDist = t;
                            bestHit = { type: 'wall', point: origin.clone().add(dir.clone().multiplyScalar(t)), distance: t,
                                normal: new THREE.Vector3(0, 1, 0) };
                        }
                        continue;
                    }
                    const t = this.rayAABBIntersect(origin, dir, c.min, c.max);
                    if (t && t < bestDist) {
                        bestDist = t;
                        bestHit = { type: 'wall', point: origin.clone().add(dir.clone().multiplyScalar(t)), distance: t,
                            normal: new THREE.Vector3(0, 1, 0) };
                    }
                }
                // Check players
                for (const p of this.players) {
                    if (!p.alive || p.id === excludeId) continue;
                    const eye = p.getEyePosition();
                    const dist = eye.distanceTo(origin);
                    if (dist > bestDist || dist < 0.5) continue;
                    const dirToPlayer = eye.sub(origin).normalize();
                    if (dir.dot(dirToPlayer) > 0.85) {
                        const hitDist = dist * (1 - Math.sqrt(1 - dir.dot(dirToPlayer) * dir.dot(dirToPlayer)));
                        const headDist = dist * dir.dot(dirToPlayer) / (dist * dir.dot(dirToPlayer));
                        // Simple player hit detection
                        const playerHalfHeight = 0.8;
                        const hitPoint = eye.clone().sub(dirToPlayer.clone().multiplyScalar(0.3));
                        const hitY = hitPoint.y - p.position.y;
                        const isHeadshot = hitY > HEADSHOT_HEIGHT;
                        if (dist < bestDist) {
                            bestDist = dist;
                            bestHit = { type: 'player', player: p, distance: dist, point: hitPoint, isHeadshot,
                                normal: dirToPlayer.clone().negate() };
                        }
                    }
                }
                return bestHit;
            }

            // ============ LOCAL CONTROLS ============
            updateLocalControls(dt) {
                const p = this.localPlayer;
                if (!p.alive) return;
                // Mouse look
                const sensitivity = 0.002;
                p.yaw -= this.mouseMove.x * sensitivity;
                p.pitch -= this.mouseMove.y * sensitivity;
                p.pitch = Math.max(-1.35, Math.min(1.35, p.pitch));
                this.mouseMove.x = 0;
                this.mouseMove.y = 0;
                // Movement
                const forward = p.getForwardVector();
                const right = p.getRightVector();
                const moveDir = new THREE.Vector3();
                if (this.input.forward) moveDir.add(forward);
                if (this.input.back) moveDir.sub(forward);
                if (this.input.left) moveDir.sub(right);
                if (this.input.right) moveDir.add(right);
                const speed = p.crouched ? CROUCH_SPEED : (this.input.sneak ? SNEAK_SPEED : RUN_SPEED);
                if (moveDir.length() > 0) {
                    moveDir.normalize().multiplyScalar(speed);
                    p.velocity.x = moveDir.x;
                    p.velocity.z = moveDir.z;
                    p.moving = true;
                } else {
                    p.velocity.x *= 0.8;
                    p.velocity.z *= 0.8;
                    p.moving = false;
                }
                p.sneaking = this.input.sneak && !p.crouched;
                p.crouched = this.input.crouch;
                // Jump
                if (this.input.jump && p.onGround) {
                    p.velocity.y = JUMP_VELOCITY;
                    p.onGround = false;
                    this.input.jump = false;
                }
                // Sprint (no separate sprint, run is sprint)
                // Reload
                if (this.input.reload && !p.reloading) {
                    p.startReload();
                    this.input.reload = false;
                }
                // Fire
                if (this.mouseDown.left || this.input.primary) {
                    this.fireLocalWeapon();
                }
                // Scope
                if (this.mouseDown.right || this.input.secondary) {
                    this.toggleLocalScope(true);
                } else {
                    this.toggleLocalScope(false);
                }
                // Position camera
                const eyePos = p.getEyePosition();
                this.camera.position.copy(eyePos);
                const aimDir = p.getAimDirection();
                this.camera.lookAt(eyePos.clone().add(aimDir));
                this.camera.rotation.z = 0;
                // Update crosshair
                const crosshair = document.getElementById('crosshair');
                if (p.scoped) {
                    crosshair.classList.add('sniper-scope');
                } else {
                    crosshair.classList.remove('sniper-scope');
                }
            }

            fireLocalWeapon() {
                const p = this.localPlayer;
                const wname = p.getCurrentWeaponName();
                const w = WEAPONS[wname];
                if (!w || w.magSize === 0) return;
                if (p.fireCooldown > 0 || p.reloading) return;
                if (p.magAmmo[wname] <= 0) {
                    if (p.reserveAmmo[wname] > 0) p.startReload();
                    return;
                }
                p.fireCooldown = w.fireRate;
                p.magAmmo[wname]--;
                const eye = p.getEyePosition();
                const dir = p.getAimDirection();
                // Spread
                const spread = w.spread * (p.moving ? 2.5 : 1) * (p.crouched ? 0.7 : 1);
                const right = p.getRightVector();
                const spreadX = (Math.random() - 0.5) * spread * 4;
                const spreadY = (Math.random() - 0.5) * spread * 4;
                const shootDir = dir.clone();
                shootDir.add(right.clone().multiplyScalar(spreadX));
                shootDir.y += spreadY;
                shootDir.normalize();
                this.handleShot(p, shootDir, eye);
                // Muzzle flash
                this.effects.addMuzzleFlash(eye.clone().add(dir.clone().multiplyScalar(0.6)), dir);
                // Shell
                this.effects.addShell(eye.clone().add(right.clone().multiplyScalar(0.7)).add(new THREE.Vector3(0, -0.3, 0)),
                    dir);
                // Auto reload if empty
                if (p.magAmmo[wname] <= 0 && p.reserveAmmo[wname] > 0) {
                    setTimeout(() => { if (p.alive) p.startReload(); }, 300);
                }
            }

            handleShot(shooter, dir, origin) {
                const wname = shooter.getCurrentWeaponName();
                const w = WEAPONS[wname];
                if (!w) return;
                audio.gunshot(w.firesound || 'pistol');
                const hit = this.raycastHitTest(origin, dir, w.range, shooter.id);
                if (hit) {
                    if (hit.type === 'player') {
                        const target = hit.player;
                        const dist = hit.distance;
                        let damage = w.damage;
                        const dropFactor = 1 - w.damageDrop * (dist / 50);
                        damage *= Math.max(0.3, dropFactor);
                        if (hit.isHeadshot) damage *= w.headshotMult;
                        if (w.pellets > 0) {
                            damage = w.damage * w.pellets * (1 - w.damageDrop * (dist / 30));
                            if (hit.isHeadshot) damage *= w.headshotMult * 0.6;
                        }
                        const actualDamage = target.takeDamage(damage, hit.isHeadshot, shooter);
                        this.effects.addImpact(hit.point, hit.normal, hit.isHeadshot ? 'headshot' : 'default');
                        if (hit.isHeadshot) {
                            audio.headshotSound();
                            if (shooter === this.localPlayer) this.showHitmarker(true);
                            else if (target === this.localPlayer) this.showDamageIndicator();
                        } else if (shooter === this.localPlayer) {
                            this.showHitmarker(false);
                            audio.hitSound();
                        }
                        this.addKillFeed(shooter, target, wname, hit.isHeadshot);
                        this.updateHUD();
                    } else {
                        this.effects.addImpact(hit.point, hit.normal);
                    }
                }
            }

            showHitmarker(headshot) {
                const el = this.hitmarkerEl;
                el.style.color = headshot ? '#ff4444' : '#ffffff';
                el.textContent = headshot ? '✕✕' : '✕';
                el.classList.remove('hit-show');
                void el.offsetWidth;
                el.classList.add('hit-show');
                setTimeout(() => el.classList.remove('hit-show'), 150);
            }

            showDamageIndicator() {
                const el = document.createElement('div');
                el.style.cssText =
                    'position:fixed;top:50%;left:50%;transform:translate(-50%,-50%);width:60px;height:60px;border:3px solid #ff0000;border-radius:50%;pointer-events:none;z-index:15;opacity:0.8;';
                document.body.appendChild(el);
                setTimeout(() => el.remove(), 200);
            }

            addKillFeed(killer, victim, weaponName, headshot) {
                const feed = document.getElementById('killfeed');
                const entry = document.createElement('div');
                entry.className = 'kill-entry';
                const w = WEAPONS[weaponName]?.name || weaponName;
                entry.textContent = `${killer.name} ${headshot ? '爆头' : ''} [${w}] ${victim.name}`;
                feed.appendChild(entry);
                setTimeout(() => entry.remove(), 3000);
                if (feed.children.length > 6) feed.removeChild(feed.firstChild);
            }

            toggleLocalScope(on) {
                const p = this.localPlayer;
                const w = p.getCurrentWeapon();
                if (w && w.scoped) {
                    p.scoped = on;
                    if (on) {
                        this.camera.fov = 25;
                        this.camera.updateProjectionMatrix();
                    } else {
                        this.camera.fov = 75;
                        this.camera.updateProjectionMatrix();
                    }
                }
            }

            equipLocalSlot(slot) {
                if (this.localPlayer && this.localPlayer.alive) {
                    this.localPlayer.equipWeapon(slot);
                }
            }

            throwLocalGrenade() {
                const p = this.localPlayer;
                if (!p || !p.alive || this.phase !== 'live') return;
                const grenades = p.weapons[5];
                if (grenades && Object.keys(grenades).length > 0) {
                    const keys = Object.keys(grenades);
                    const gName = keys[0];
                    if (grenades[gName]) {
                        grenades[gName] = false;
                        const dir = p.getAimDirection();
                        dir.y += 0.3;
                        this.throwGrenade(p, gName, dir);
                    }
                }
            }

            throwGrenade(player, grenadeName, dir) {
                const pos = player.getEyePosition();
                const velocity = dir.clone().multiplyScalar(14);
                velocity.y += 5;
                const grenade = {
                    type: grenadeName,
                    position: pos.clone(),
                    velocity,
                    owner: player,
                    timer: grenadeName === 'hegrenade' ? 1.5 : (grenadeName === 'flashbang' ? 1.5 : (grenadeName ===
                        'smokegrenade' ? 2.0 : 0.5)),
                    life: 2.5
                };
                // Visual representation
                const geo = new THREE.SphereGeometry(0.15, 8, 8);
                const colors = { hegrenade: 0x444444, flashbang: 0xDDDDDD, smokegrenade: 0x666666, molotov: 0xCC4400 };
                const mat = new THREE.MeshLambertMaterial({ color: colors[grenadeName] || 0x555555 });
                const mesh = new THREE.Mesh(geo, mat);
                mesh.position.copy(pos);
                this.scene.add(mesh);
                grenade.mesh = mesh;
                if (!this.activeGrenades) this.activeGrenades = [];
                this.activeGrenades.push(grenade);
                audio.gunshot('throw');
                // Update grenade physics
                const updateGrenade = (dt) => {
                    if (!grenade.mesh || !grenade.mesh.parent) return;
                    grenade.velocity.y -= GRAVITY * dt;
                    grenade.position.add(grenade.velocity.clone().multiplyScalar(dt));
                    grenade.mesh.position.copy(grenade.position);
                    grenade.life -= dt;
                    // Check collision with ground/walls
                    const below = grenade.position.clone();
                    below.y -= 0.2;
                    if (this.checkCollisionsAt(player, below) || grenade.position.y < 0.2) {
                        grenade.position.y = Math.max(0.2, grenade.position.y);
                        this.explodeGrenade(grenade);
                        return;
                    }
                    if (grenade.life <= 0) {
                        this.explodeGrenade(grenade);
                    }
                };
                grenade.updateFn = updateGrenade;
                // Add to update loop
                if (!this.grenadeUpdateList) this.grenadeUpdateList = [];
                this.grenadeUpdateList.push(grenade);
            }

            explodeGrenade(grenade) {
                if (grenade.mesh) {
                    this.scene.remove(grenade.mesh);
                    grenade.mesh = null;
                }
                if (this.grenadeUpdateList) {
                    this.grenadeUpdateList = this.grenadeUpdateList.filter(g => g !== grenade);
                }
                const pos = grenade.position;
                if (grenade.type === 'hegrenade') {
                    audio.explosion();
                    this.effects.addImpact(pos, new THREE.Vector3(0, 1, 0));
                    const flash = new THREE.PointLight(0xff8800, 5, 12);
                    flash.position.copy(pos);
                    this.scene.add(flash);
                    setTimeout(() => this.scene.remove(flash), 100);
                    for (const p of this.players) {
                        if (p.alive) {
                            const dist = p.position.distanceTo(pos);
                            if (dist < 12) {
                                const damage = Math.round(100 * (1 - dist / 15));
                                if (damage > 0) p.takeDamage(Math.min(damage, 100), false, grenade.owner);
                            }
                        }
                    }
                } else if (grenade.type === 'flashbang') {
                    audio.explosion();
                    const flash = new THREE.PointLight(0xffffff, 8, 15);
                    flash.position.copy(pos);
                    this.scene.add(flash);
                    setTimeout(() => this.scene.remove(flash), 80);
                    for (const p of this.players) {
                        if (p.alive) {
                            const dist = p.position.distanceTo(pos);
                            const eyePos = p.getEyePosition();
                            const dirToFlash = pos.clone().sub(eyePos).normalize();
                            const aim = p.getAimDirection();
                            const facing = dirToFlash.dot(aim);
                            if (dist < 20 && facing > 0.3) {
                                p.flashBlindness = Math.max(p.flashBlindness, (1 - dist / 25) * (0.5 + facing * 0.5) *
                                    4);
                                if (p === this.localPlayer) {
                                    this.updateFlashOverlay();
                                }
                            }
                        }
                    }
                } else if (grenade.type === 'smokegrenade') {
                    this.effects.addSmoke(pos, 3);
                } else if (grenade.type === 'molotov') {
                    this.effects.addFlame(pos, 5);
                    // Fire damage per second
                    const fireInterval = setInterval(() => {
                        for (const p of this.players) {
                            if (p.alive && p.position.distanceTo(pos) < 3) {
                                p.takeDamage(5, false, grenade.owner);
                            }
                        }
                    }, 1000);
                    setTimeout(() => clearInterval(fireInterval), 5000);
                }
            }

            tryInteract() {
                const p = this.localPlayer;
                if (!p || !p.alive || this.phase !== 'live') return;
                // Plant bomb
                if (p.team === 'T' && this.bombCarrier === p && !this.bombPlanted) {
                    for (const site of this.bombSites) {
                        if (p.position.distanceTo(new THREE.Vector3(site.x, site.y, site.z)) < site.radius) {
                            p.isPlanting = true;
                            p.plantTimer = PLANT_TIME;
                            audio.plantBomb();
                            this.showNotice('正在安装炸弹...', '#e8b830');
                            break;
                        }
                    }
                }
                // Defuse bomb
                if (p.team === 'CT' && this.bombPlanted) {
                    const dist = p.position.distanceTo(this.bombPosition);
                    if (dist < 3) {
                        p.isDefusing = true;
                        p.defuseTimer = p.hasDefuseKit ? DEFUSE_TIME_KIT : DEFUSE_TIME;
                        audio.defuseBomb();
                        this.showNotice('正在拆除炸弹...', '#4a9ad8');
                    }
                }
            }

            completePlant(player) {
                this.bombPlanted = true;
                this.bombPosition = player.position.clone();
                this.bombTimer = BOMB_TIMER;
                this.plantedBombMesh = this.effects.addBombPlanted(this.bombPosition.clone());
                audio.explosion();
                this.showNotice('炸弹已安装!', '#ff4444');
                this.updateHUD();
            }

            completeDefuse(player) {
                this.bombPlanted = false;
                if (this.plantedBombMesh) {
                    this.scene.remove(this.plantedBombMesh);
                    this.plantedBombMesh = null;
                }
                this.endRound('CT', '炸弹已拆除');
                this.showNotice('炸弹已拆除!', '#3dd84a');
            }

            // ============ BOT OBJECTIVES ============
            updateBotObjectives(dt) {
                for (const p of this.players) {
                    if (!p.isBot || !p.alive || !p.botAI) continue;
                    // Plant bomb
                    if (p.team === 'T' && this.bombCarrier === p && !this.bombPlanted) {
                        for (const site of this.bombSites) {
                            if (p.position.distanceTo(new THREE.Vector3(site.x, site.y, site.z)) < site.radius) {
                                if (!p.isPlanting) {
                                    p.isPlanting = true;
                                    p.plantTimer = PLANT_TIME;
                                }
                                break;
                            }
                        }
                    }
                    // Defuse bomb
                    if (p.team === 'CT' && this.bombPlanted) {
                        const dist = p.position.distanceTo(this.bombPosition);
                        if (dist < 3 && !p.isDefusing) {
                            p.isDefusing = true;
                            p.defuseTimer = p.hasDefuseKit ? DEFUSE_TIME_KIT : DEFUSE_TIME;
                        }
                    }
                }
            }

            updateBotFire(p, dt) {
                if (!p.isBot || !p.alive || !p.botAI || p.botAI.state !== 'combat') return;
                // Bot firing handled in BotBrain.combatUpdate
            }

            endRound(winnerTeam, reason) {
                if (this.phase === 'round_end') return;
                this.phase = 'round_end';
                this.roundEndTimer = 3;
                this.winnerTeam = winnerTeam;
                this.roundEndReason = reason;
                this.score[winnerTeam] = (this.score[winnerTeam] || 0) + 1;
                audio.roundEnd(winnerTeam === this.localTeam);
                const winText = winnerTeam === this.localTeam ? '胜利!' : '失败!';
                const color = winnerTeam === this.localTeam ? '#3dd84a' : '#ff4444';
                this.showNotice(`${winText} ${reason}`, color);
                this.updateHUD();
                if (this.bombPlanted && winnerTeam === 'CT') {
                    if (this.plantedBombMesh) {
                        this.scene.remove(this.plantedBombMesh);
                        this.plantedBombMesh = null;
                    }
                    this.bombPlanted = false;
                }
                // Update team scores UI
                document.getElementById('score-t').textContent = `T: ${this.score.T || 0}`;
                document.getElementById('score-ct').textContent = `CT: ${this.score.CT || 0}`;
            }

            endGame() {
                this.gameOver = true;
                const winner = (this.score.T || 0) > (this.score.CT || 0) ? 'T' : 'CT';
                const isLocalWin = winner === this.localTeam;
                this.phase = 'round_end';
                this.roundEndTimer = 99999;
                this.showNotice(`游戏结束! ${winner} 获胜! ${isLocalWin ? '你的阵营胜利!' : '你的阵营失败!'}`, isLocalWin ?
                    '#3dd84a' : '#ff4444');
                // Show restart button
                setTimeout(() => {
                    const restartBtn = document.createElement('button');
                    restartBtn.className = 'menu-btn';
                    restartBtn.style.cssText =
                        'position:fixed;top:55%;left:50%;transform:translateX(-50%);z-index:200;';
                    restartBtn.textContent = '回到主菜单';
                    restartBtn.onclick = () => {
                        location.reload();
                    };
                    document.body.appendChild(restartBtn);
                }, 1500);
            }

            onPlayerDeath(player, attacker) {
                if (player === this.localPlayer) {
                    this.showNotice('你被击杀了!', '#ff4444');
                }
                const aliveT = this.players.filter(p => p.team === 'T' && p.alive);
                const aliveCT = this.players.filter(p => p.team === 'CT' && p.alive);
                if (this.phase === 'live') {
                    if (aliveT.length === 0 && !this.bombPlanted) this.endRound('CT', '消灭所有恐怖分子');
                    else if (aliveCT.length === 0) this.endRound('T', '消灭所有反恐精英');
                }
                this.updateHUD();
            }

            updateTeamScoresForKill() {
                // Track for end of round logic
            }

            showNotice(text, color = '#fff') {
                const container = document.getElementById('notifications');
                const notice = document.createElement('div');
                notice.className = 'notice';
                notice.textContent = text;
                notice.style.color = color || '#fff';
                container.appendChild(notice);
                setTimeout(() => notice.remove(), 3000);
                if (container.children.length > 4) container.removeChild(container.firstChild);
            }

            toggleBuyMenu() {
                if (this.phase !== 'buy' || !this.localPlayer || !this.localPlayer.alive) return;
                this.buyMenuVisible = !this.buyMenuVisible;
                if (this.buyMenuVisible) this.showBuyMenu();
                else this.hideBuyMenu();
            }

            showBuyMenu() {
                const menu = document.getElementById('buy-menu');
                menu.style.display = 'flex';
                menu.innerHTML = `
                    <h2 style="color:#e8b830;text-align:center;margin-bottom:5px;">购买菜单 - $${this.localPlayer.money}</h2>
                    ${WEAPON_CATEGORIES.map(cat => `
                        <div class="category">
                            <h3>${WEAPON_DISPLAY_NAMES[cat]}</h3>
                            ${Object.entries(WEAPONS).filter(([k, v]) => v.category === cat && v.price > 0).map(([k, v]) => `
                                <div class="buy-item ${this.localPlayer.money < v.price ? 'disabled' : ''}" data-item="${k}">
                                    <div class="buy-name">${v.name}</div>
                                    <div class="buy-price">$${v.price}</div>
                                </div>
                            `).join('')}
                        </div>
                    `).join('')}
                    <button id="buy-close">关闭 (B)</button>
                `;
                menu.querySelectorAll('.buy-item').forEach(el => {
                    el.addEventListener('click', () => {
                        const itemName = el.dataset.item;
                        if (this.localPlayer.buyItem(itemName)) {
                            this.showBuyMenu();
                            this.updateHUD();
                        }
                    });
                });
                menu.querySelector('#buy-close').addEventListener('click', () => this.toggleBuyMenu());
            }

            hideBuyMenu() {
                this.buyMenuVisible = false;
                document.getElementById('buy-menu').style.display = 'none';
            }

            toggleScoreboard() {
                this.scoreboardVisible = !this.scoreboardVisible;
                const sb = document.getElementById('scoreboard');
                if (this.scoreboardVisible) {
                    sb.style.display = 'block';
                    sb.innerHTML = `
                        <h3 style="color:#e8b830;text-align:center;margin-bottom:8px;">积分榜</h3>
                        <table>
                            <tr><th>玩家</th><th>阵营</th><th>K/D</th><th>金钱</th><th>得分</th></tr>
                            ${this.players.map(p => `
                                <tr>
                                    <td>${p.name}${p === this.localPlayer ? ' (你)' : ''}</td>
                                    <td style="color:${p.team === 'T' ? '#e8b830' : '#4a9ad8'}">${p.team}</td>
                                    <td>${p.kills}/${p.deaths}</td>
                                    <td>$${p.money}</td>
                                    <td>${p.score}</td>
                                </tr>
                            `).join('')}
                        </table>
                    `;
                } else {
                    sb.style.display = 'none';
                }
            }

            hideScoreboard() {
                this.scoreboardVisible = false;
                document.getElementById('scoreboard').style.display = 'none';
            }

            updateHUD() {
                const p = this.localPlayer;
                if (!p) return;
                document.getElementById('hud-hp').textContent = Math.round(p.health);
                document.getElementById('hud-hp').style.color = p.health > 60 ? 'var(--health)' : (p.health > 25 ?
                    '#ffaa00' : '#ff3333');
                document.getElementById('hud-armor').textContent = Math.round(p.armor);
                const wname = p.getCurrentWeaponName();
                const w = WEAPONS[wname];
                document.getElementById('hud-ammo').textContent = w && w.magSize > 0 ?
                    `${p.magAmmo[wname] || 0} / ${p.reserveAmmo[wname] || 0}` : '∞';
                document.getElementById('hud-weapon').textContent = w ? w.name : '刀';
                document.getElementById('hud-money').textContent = `$${p.money}`;
                // Timer
                const timerEl = document.getElementById('round-timer');
                const displayTime = this.phase === 'buy' ? this.buyTimer : (this.bombPlanted ? this.bombTimer : this
                    .roundTimer);
                const mins = Math.floor(Math.max(0, displayTime) / 60);
                const secs = Math.floor(Math.max(0, displayTime) % 60);
                timerEl.textContent = displayTime > ROUND_TIME + 1 ? '∞' :
                    `${mins}:${secs.toString().padStart(2, '0')}`;
                timerEl.classList.toggle('urgent', displayTime < 10 && this.phase === 'live');
                // Phase label
                const phaseEl = document.getElementById('round-phase');
                if (this.phase === 'buy') phaseEl.textContent = '购买阶段';
                else if (this.phase === 'live') phaseEl.textContent = this.bombPlanted ? '炸弹已安装!' : '行动阶段';
                else if (this.phase === 'round_end') phaseEl.textContent = this.roundEndReason || '回合结束';
                document.getElementById('score-t').textContent = `T: ${this.score.T || 0}`;
                document.getElementById('score-ct').textContent = `CT: ${this.score.CT || 0}`;
            }

            updateFlashOverlay() {
                const p = this.localPlayer;
                if (p && p.alive && p.flashBlindness > 0) {
                    const opacity = Math.min(1, p.flashBlindness / 3);
                    this.flashOverlayEl.style.opacity = opacity;
                } else {
                    this.flashOverlayEl.style.opacity = 0;
                }
            }

            updateRadar() {
                const canvas = document.getElementById('radar-canvas');
                const ctx = canvas.getContext('2d');
                const mapData = this.mapData;
                if (!mapData) return;
                ctx.fillStyle = 'rgba(20,20,16,0.7)';
                ctx.fillRect(0, 0, 140, 140);
                const bounds = mapData.bounds;
                const rangeX = bounds.maxX - bounds.minX;
                const rangeZ = bounds.maxZ - bounds.minZ;
                const scale = 130 / Math.max(rangeX, rangeZ);
                const cx = 70 + (-((bounds.minX + bounds.maxX) / 2) * scale);
                const cz = 70 + (-((bounds.minZ + bounds.maxZ) / 2) * scale);
                // Draw bomb sites
                for (const site of this.bombSites) {
                    ctx.fillStyle = '#e8b830';
                    ctx.beginPath();
                    ctx.arc(cx + site.x * scale, cz + site.z * scale, 5, 0, Math.PI * 2);
                    ctx.fill();
                    ctx.fillStyle = '#fff';
                    ctx.font = '7px Arial';
                    ctx.fillText(site.name, cx + site.x * scale + 6, cz + site.z * scale + 3);
                }
                // Draw bomb
                if (this.bombPosition && this.bombPlanted) {
                    ctx.fillStyle = '#ff0000';
                    ctx.beginPath();
                    ctx.arc(cx + this.bombPosition.x * scale, cz + this.bombPosition.z * scale, 4, 0, Math.PI * 2);
                    ctx.fill();
                }
                // Draw players
                for (const p of this.players) {
                    if (!p.alive) continue;
                    const color = p.team === 'T' ? '#e8b830' : '#4a9ad8';
                    if (p === this.localPlayer) {
                        ctx.fillStyle = '#fff';
                        ctx.beginPath();
                        ctx.arc(cx + p.position.x * scale, cz + p.position.z * scale, 5, 0, Math.PI * 2);
                        ctx.fill();
                    } else {
                        ctx.fillStyle = color;
                        ctx.beginPath();
                        ctx.arc(cx + p.position.x * scale, cz + p.position.z * scale, 3, 0, Math.PI * 2);
                        ctx.fill();
                    }
                }
            }

            updateSpectatorIfNeeded() {
                const ui = document.getElementById('spectator-ui');
                if (this.localPlayer && !this.localPlayer.alive && this.phase === 'live') {
                    ui.style.display = 'block';
                    const specTarget = this.getSpectatorTarget();
                    if (specTarget) {
                        const eye = specTarget.getEyePosition();
                        this.camera.position.copy(eye);
                        const dir = specTarget.getAimDirection();
                        this.camera.lookAt(eye.clone().add(dir));
                        ui.textContent = `观战: ${specTarget.name}`;
                    }
                } else {
                    ui.style.display = 'none';
                }
            }

            getSpectatorTarget() {
                const alivePlayers = this.players.filter(p => p.alive && p !== this.localPlayer);
                if (alivePlayers.length === 0) return null;
                if (this.spectatorIndex >= alivePlayers.length) this.spectatorIndex = 0;
                return alivePlayers[this.spectatorIndex];
            }

            muteAudio() {
                if (audio.masterGain) {
                    audio.masterGain.gain.value = audio.masterGain.gain.value > 0 ? 0 : 0.6;
                }
            }
        }

        // ============ START ============
        const game = new Game();
        console.log('CS: Tactical Strike loaded. Click START to play.');
        console.log('Maps: de_dust2 (classic), de_warehouse, de_citadel');
        console.log('Controls: WASD + mouse, B=Buy, R=Reload, G=Grenade, E=Interact, Tab=Scoreboard, M=Mute');
        console.log('Full feature list: 3 maps, Bot AI (3 difficulties), economy system, bomb mode, all weapon types');
        console.log('Dust2 map includes: A site, B site, Mid, A Long, A Short, A Pit, A Ramp, Mid Doors, Double Doors, Xbox, B Tunnel, B Door, B Platform, CT Spawn, Long Doors, cover crates, sniper lines, bomb sites, defensive positions, attack routes, CT rotation routes, T flank routes');
    </script>
</body>
</html>
